billing:{name:'Betaling',panel_title:'💳 Betaling & faktura',panel_message:'Har du spørgsmål til betaling, faktura eller et køb? Opret en ticket her.',button_label:'💳 Betaling',ticket_name:'betaling-{username}',welcome_message:'Hej {mention}! Send gerne ordre-/fakturanummer og en kort beskrivelse. Del aldrig adgangskoder eller betalingskortoplysninger.',close_message:'Din betalings-ticket er lukket. Tak for din henvendelse.'},
technical:{name:'Teknisk problem',panel_title:'🔧 Teknisk support',panel_message:'Oplever du fejl eller tekniske problemer? Opret en ticket og beskriv fejlen.',button_label:'🔧 Teknisk hjælp',ticket_name:'teknisk-{username}',welcome_message:'Hej {mention}! Beskriv hvad der sker, hvad du forventede skulle ske, og vedhæft gerne screenshot eller fejltekst.',close_message:'Din tekniske ticket er nu lukket.'},
report:{name:'Spiller-rapport',panel_title:'🚨 Spiller-rapport',panel_message:'Rapportér regelbrud eller en spiller til staff. Vedhæft gerne dokumentation.',button_label:'🚨 Opret rapport',ticket_name:'rapport-{username}',welcome_message:'Hej {mention}! Skriv spillerens navn/ID, hvad der skete, tidspunkt og vedhæft bevis hvis muligt.',close_message:'Rapporten er behandlet og ticketen er lukket.'},
staff:{name:'Staff-klage',panel_title:'👮 Staff-klage',panel_message:'Har du en klage over et staff-medlem? Opret en privat ticket her.',button_label:'👮 Opret staff-klage',ticket_name:'staff-klage-{username}',welcome_message:'Hej {mention}! Beskriv hændelsen sagligt med staff-navn, tidspunkt og eventuel dokumentation.',close_message:'Din staff-klage er behandlet og ticketen er lukket.'},
ban:{name:'Ban Appeal',panel_title:'🔨 Ban Appeal',panel_message:'Mener du, at dit ban bør genovervejes? Send en ban appeal.',button_label:'🔨 Opret Ban Appeal',ticket_name:'ban-appeal-{username}',welcome_message:'Hej {mention}! Angiv dit spiller-ID, ban-årsag og hvorfor du mener, at dit ban bør genovervejes.',close_message:'Din Ban Appeal er færdigbehandlet.'},
whitelist:{name:'Whitelist',panel_title:'✅ Whitelist',panel_message:'Har du spørgsmål til whitelist eller ønsker hjælp med din ansøgning? Opret en ticket.',button_label:'✅ Whitelist',ticket_name:'whitelist-{username}',welcome_message:'Hej {mention}! Fortæl hvad du har brug for hjælp til vedrørende whitelist.',close_message:'Din whitelist-ticket er nu lukket.'},
partner:{name:'Partnerskab',panel_title:'🤝 Partnerskab',panel_message:'Interesseret i et samarbejde eller partnerskab? Kontakt os her.',button_label:'🤝 Partnerskab',ticket_name:'partner-{username}',welcome_message:'Hej {mention}! Fortæl om dig/jer, hvad samarbejdet går ud på, og relevante links eller informationer.',close_message:'Tak for din partnerskabsforespørgsel. Ticketen er nu lukket.'},
other:{name:'Andet',panel_title:'📩 Kontakt os',panel_message:'Passer din henvendelse ikke i de andre kategorier? Opret en ticket her.',button_label:'📩 Opret ticket',ticket_name:'ticket-{username}',welcome_message:'Hej {mention}! Beskriv din henvendelse så detaljeret som muligt.',close_message:'Din ticket er nu lukket. Tak for din henvendelse.'}
};
function setField(name,value){var el=document.querySelector('[name="'+name+'"]');if(el)el.value=value;}
document.addEventListener('click',function(e){
 var t=e.target.closest('.ms-template');if(t){var p=templates[t.dataset.template];if(!p)return;['panel_title','panel_message','button_label','ticket_name','welcome_message','close_message'].forEach(function(k){setField(k,p[k]||'');});var ok=document.getElementById('template-applied');if(ok){ok.querySelector('span').textContent=p.name+'-templaten';ok.style.display='block';}document.getElementById('field-panel_title')?.scrollIntoView({behavior:'smooth',block:'center'});return;}
 var b=e.target.closest('.ms-var');if(!b)return;var f=document.getElementById(lastMessage)||document.getElementById('field-panel_message');if(!f)return;var s=f.selectionStart||f.value.length,en=f.selectionEnd||f.value.length,v=b.dataset.value;f.value=f.value.substring(0,s)+v+f.value.substring(en);f.focus();f.selectionStart=f.selectionEnd=s+v.length;
});
})();
